text":"conversation"}],"c":"d"},{"n":155,"p":27,"q":"It couldn’t come to lunch today ……….","options":[{"label":"a","text":"but I was ill."},{"label":"b","text":"so I was ill"},{"label":"c","text":"because I was ill"},{"label":"d","text":"then I was ill"}],"c":"c"},{"n":156,"p":27,"q":"Some children may communicate via ……… nodding or very brief utterance.","options":[{"label":"a","text":"sounds"},{"label":"b","text":"rests"},{"label":"c","text":"speech"},{"label":"d","text":"gestures"}],"c":"d"},{"n":157,"p":27,"q":"In a research, students from ten countries …………… were questioned about the usage of electronic devices.","options":[{"label":"a","text":"surround the world"},{"label":"b","text":"around the world"},{"label":"c","text":"from the world"},{"label":"d","text":"on the world"}],"c":"b"},{"n":158,"p":27,"q":"The ring I bought is expensive as it is made of gold. Synonym of Expensive is ………","options":[{"label":"a","text":"costly"},{"label":"b","text":"reasonable"},{"label":"c","text":"worthiest"},{"label":"d","text":"cheap"}],"c":"a"},{"n":159,"p":28,"q":"Jenny is bilingual. She ……… two languages.","options":[{"label":"a","text":"speaks"},{"label":"b","text":"speak"},{"label":"c","text":"speaking"},{"label":"d","text":"spoke"}],"c":"a"},{"n":160,"p":28,"q":"There has been a ………… improvement in her attitude.","options":[{"label":"a","text":"decreasing"},{"label":"b","text":"increasing"},{"label":"c","text":"consistent"},{"label":"d","text":"submissive"}],"c":"c"},{"n":161,"p":28,"q":"Did you talk to your tutor about your assignment yesterday? Choose the correct answer……..","options":[{"label":"a","text":"Yes. I done."},{"label":"b","text":"Yes. I do"},{"label":"c","text":"Yes. I don’t."},{"label":"d","text":"Yes. I did."}],"c":"d"},{"n":162,"p":28,"q":"Take a few moments to pause, slow down, …….With the audience and then continue","options":[{"label":"a","text":"see an eye contact"},{"label":"b","text":"make an eye contact"},{"label":"c","text":"do an eye contact"},{"label":"d","text":"take an eye contact"}],"c":"b"},{"n":163,"p":28,"q":"He began by pitying his big brother and ended by ……….","options":[{"label":"a","text":"sympathizing"},{"label":"b","text":"emphasizing"},{"label":"c","text":"popularizing"},{"label":"d","text":"summarizing"}],"c":"a"},{"n":164,"p":28,"q":"There is a strong ………… for lowering the prices by the customers.","options":[{"label":"a","text":"argument"},{"label":"b","text":"lecture"},{"label":"c","text":"speech"},{"label":"d","text":"message"}],"c":"a"},{"n":165,"p":29,"q":"Poor posture can cause neck ache, head ache and breathing problems. The word similar in meaning to posture is ………","options":[{"label":"a","text":"position at home"},{"label":"b","text":"position at office"},{"label":"c","text":"position of mind"},{"label":"d","text":"position of body"}],"c":"d"},{"n":166,"p":29,"q":"We edited out some unnecessary Words or sentences from the draft. Antonym of draft is ……...","options":[{"label":"a","text":"outline"},{"label":"b","text":"finished work"},{"label":"c","text":"rough draft"},{"label":"d","text":"blue print"}],"c":"b"}]$el099_src$::jsonb)
), inserted_questions AS (
 INSERT INTO public.intensive_questions
 (id,course_id,exam_category,skill,type,difficulty,prompt,grading_mode,marks,
  reference_source,reference_unit,reference_page,tags)
 SELECT md5('NUMO:EL099:Q2:GRAM:'||(row->>'n'))::uuid,
  (SELECT id FROM public.intensive_courses WHERE code='EL099'),'QUIZ 2',
  CASE WHEN (row->>'q')~*'(antonym|synonym|means|mean\?|term|word similar|what is .*word|responsible|what part of speech)' THEN 'Vocabulary' ELSE 'Grammar' END,
  'MULTIPLE_CHOICE','MEDIUM',row->>'q','AUTO',1,
  'EL099 Quiz2 Compilations · Grammar and Vocabulary PDF',
  'Grammar and Vocabulary',row->>'p',
  ARRAY['EL099-Q2-GV','SOURCE_Q='||(row->>'n'),'SOURCE_PDF_PAGE='||(row->>'p')]
 FROM data ON CONFLICT(id) DO NOTHING RETURNING id
), inserted_options AS (
 INSERT INTO public.intensive_question_options
 (id,question_id,label,value,is_correct,position)
 SELECT md5('NUMO:EL099:Q2:GRAM:'||(d.row->>'n')||':OPTION:'||(o.value->>'label'))::uuid,
  q.id,o.value->>'label',o.value->>'text',
  (o.value->>'label')=(d.row->>'c'), ascii(o.value->>'label')-96
 FROM data d
 JOIN inserted_questions q ON q.id=md5('NUMO:EL099:Q2:GRAM:'||(d.row->>'n'))::uuid
 CROSS JOIN LATERAL jsonb_array_elements(d.row->'options') AS o(value)
 ON CONFLICT(id) DO NOTHING RETURNING id
), inserted_exam_questions AS (
 INSERT INTO public.intensive_exam_questions(exam_id,section_id,question_id,marks,position)
 SELECT md5('NUMO:EL099:QUIZ2:THREE_SECTIONS')::uuid,
        md5('NUMO:EL099:QUIZ2:SECTION:1')::uuid,q.id,1,(d.row->>'n')::int
 FROM data d JOIN inserted_questions q
 ON q.id=md5('NUMO:EL099:Q2:GRAM:'||(d.row->>'n'))::uuid
 ON CONFLICT DO NOTHING RETURNING id
)
SELECT (SELECT COUNT(*) FROM inserted_questions) AS questions_added,
       (SELECT COUNT(*) FROM inserted_options) AS choices_added,
       (SELECT COUNT(*) FROM inserted_exam_questions) AS exam_links_added;